104: // Inserts all given payloads into the given status. Will overwrite existing
105: // payloads if they exist with the same key.
106: inline void InsertPayloads(
107:     ::tsl::Status& status,
108:     const std::unordered_map<std::string, std::string>& payloads) {
109:   for (const auto& payload : payloads) {
110:     status.SetPayload(payload.first, absl::Cord(payload.second));
