114: // Copies all payloads from one Status to another. Will overwrite existing
115: // payloads in the destination if they exist with the same key.
116: inline void CopyPayloads(const ::tsl::Status& from, ::tsl::Status& to) {
117:   from.ForEachPayload([&to](::tsl::StringPiece key, const absl::Cord& value) {
