174:     /// Base VTable specification.
175:     struct vtable_type
176:     {
177:         // Note: The caller is responssible for doing .vtable = nullptr after destructful operations
178:         // such as destroy() and/or move().
179: 
180:         /// The type of the object this vtable is for.
181:         const std::type_info& (*type)() noexcept;
182: 
183:         /// Destroys the object in the union.
184:         /// The state of the union after this call is unspecified, caller must ensure not to use src anymore.
185:         void (*destroy)(storage_union&) noexcept;
186: 
187:         /// Copies the **inner** content of the src union into the yet unitialized dest union.
188:         /// As such, both inner objects will have the same state, but on separate memory locations.
189:         void (*copy)(const storage_union& src, storage_union& dest);
190: 
191:         /// Moves the storage from src to the yet unitialized dest union.
192:         /// The state of src after this call is unspecified, caller must ensure not to use src anymore.
193:         void (*move)(storage_union& src, storage_union& dest) noexcept;
194: 
195:         /// Exchanges the storage between lhs and rhs.
196:         void (*swap)(storage_union& lhs, storage_union& rhs) noexcept;
197:     };
